insert into public.site_pages (slug,title,summary,content_markdown,page_type,status,seo_title,seo_description)
values
('home','IntelliStack Systems','One World. One System. One Intelligent Network.','## One World. One System. One Intelligent Network.\n\nIntelliStack Systems is developing a connected enterprise platform designed to bring people, operations, information, and intelligent workflows into one coordinated environment.\n\n### Maximus Optimus Command Center\n\nA unified command workspace for business operations, identity and access, service delivery, workforce coordination, security, governance, productivity, and collaboration.\n\n### IntelliSphere\n\nThe IntelliSphere suite brings together native business and productivity experiences, with connected external services where integrations are approved and configured.\n\n**Editorial review required:** confirm the public product descriptions, company history, leadership details, and contact information before publication.','marketing','draft','IntelliStack Systems | One World. One System. One Intelligent Network.','Explore IntelliStack Systems and the Maximus Optimus Command Center.'),
('products','Products and IntelliSphere','Explore the IntelliSphere business and productivity suite.','## IntelliSphere Products\n\nThe planned suite includes IntelliPay, IntelliTax, IntelliWord, IntelliNotes, IntelliSheets, IntelliSlides, IntelliText, IntelliDrive, IntelliForms, IntelliStudio, IntelliChat, IntelliCalendar, IntelliDesk, IntelliSync, and related services.\n\nProduct availability, features, pricing, service commitments, and integrations must be confirmed against the live product catalog before publication.','marketing','draft','IntelliSphere Products | IntelliStack Systems','Explore IntelliSphere products and services from IntelliStack Systems.'),
('solutions','Enterprise Solutions','Connected workflows for enterprise operations, workforce, security, and governance.','## Enterprise Solutions\n\nExplore connected approaches for enterprise command operations, identity and access management, service desk operations, security and network operations, governance and compliance, workforce coordination, productivity, and collaboration.\n\nSolution descriptions and customer outcomes must be validated before publication.','marketing','draft','Enterprise Solutions | IntelliStack Systems','Explore enterprise operations and workflow solutions from IntelliStack Systems.'),
('partners','Partners and Integrations','Connect with IntelliStack through approved business and technology partnerships.','## Partner with IntelliStack\n\nWe are developing partner pathways for technology providers, implementation partners, service providers, vendors, and business collaborators.\n\nNo partner status, endorsement, certification, or commercial arrangement should be represented as active until formally approved. Contact the team through the Contact page for partnership inquiries.','marketing','draft','Partners | IntelliStack Systems','Explore business and technology partnership opportunities.'),
('careers','Careers','Explore future opportunities with IntelliStack Systems.','## Careers at IntelliStack Systems\n\nThis page is reserved for verified job openings, role descriptions, hiring practices, accessibility accommodations, and candidate privacy information. No role is advertised as open until approved and published by the company.','marketing','draft','Careers | IntelliStack Systems','Career opportunities and hiring information at IntelliStack Systems.'),
('social','Connect with IntelliStack','Find official IntelliStack Systems social media channels.','## Connect with IntelliStack\n\nOfficial social media profiles are managed centrally. Only verified company-owned profile URLs should be published. Use the official links displayed on this page after they have been approved in Website and Communications administration.','marketing','draft','Connect with IntelliStack | Social Media','Official IntelliStack Systems social media profiles and channels.'),
('cookie-preferences','Cookie and Tracking Preferences','Information about cookies and optional tracking technologies.','## Cookie and Tracking Preferences\n\n**Draft — requires privacy/legal review and verification of technologies actually deployed.** This page must describe necessary, analytics, personalization, and advertising technologies only when they are present, with applicable consent controls and regional choices.','legal','draft','Cookie Preferences | IntelliStack Systems','Cookie and tracking information requiring legal review.'),
('acceptable-use','Acceptable Use Policy','Rules for appropriate use of IntelliStack services.','## Acceptable Use Policy\n\n**Draft — not an enforceable policy until legal review and approval.** Define prohibited conduct, security testing boundaries, content rules, abuse reporting, enforcement, appeals, and service-specific conditions.','legal','draft','Acceptable Use Policy | IntelliStack Systems','Draft acceptable use policy requiring legal approval.'),
('data-protection','Data Protection Information','Information about data protection, privacy requests, and processing safeguards.','## Data Protection Information\n\n**Draft — requires privacy counsel review.** Include verified controller and processor roles, processing purposes, retention, data subject rights, international transfer safeguards, subprocessors, and contact channels.','legal','draft','Data Protection | IntelliStack Systems','Data protection information requiring privacy review.')
